<script setup lang="ts">import {computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import WindowComparison from '../components/WindowComparison.vue';import {number,percent} from '../utils/format';const props=defineProps<{data:Workspace}>();const emit=defineEmits<{go:[string]}>();const run=computed(()=>props.data.runs.find(r=>r.status==='completed'));;
</script><template><PageHeading code="01 / CAPACITY OBSERVATORY" title="让窗口安排，经得起追问。" description="云岫实验室收样组 · 20人。先核查输入，再比较理论稳态与有限时域的等待。"/><div class="overview-board"><section class="main-board"><span class="lab-label">当前预演 / OPEN COUNTERS</span><div class="window-count"><b>{{run?.result.analytic.windows||'—'}}</b><span>个窗口<br/><small>同质服务 / 先到先服务</small></span></div><div class="board-metrics"><div><small>仿真平均等待</small><strong>{{number(run?.result.simulation.mean_wait_minutes)}}<i>分钟</i></strong></div><div><small>理论负荷ρ</small><strong>{{percent(run?.result.analytic.rho)}}</strong></div><div><small>稳态条件</small><strong class="word">{{run?.result.analytic.stable?'ρ < 1':'ρ ≥ 1'}}</strong></div></div><button class="board-button" @click="emit('go','results')">展开等待与负荷　↗</button></section><aside class="field-note"><span class="eyebrow">FIELD NOTE / 001</span><h2>利用率很高，<br/>等待可能更长。</h2><p>ρ接近1时，排队等待会非线性增加。多开一个窗口的效果，应结合到达率、单窗口服务率与高峰时段判断。</p><div><b>{{data.datasets.reduce((n,d)=>n+d.rows.length,0)}}</b><span>条模拟时长观测</span></div></aside></div><section v-if="run" class="paper"><div class="section-heading"><h2>同一输入率，比较窗口数</h2><span>ERLANG-C · 分钟口径</span></div><WindowComparison :rows="run.result.comparison" :selected="run.result.analytic.windows"/></section><div class="process-line"><span><b>01</b>核查观测与时段</span><span><b>02</b>预演窗口与等待</span><span><b>03</b>复核假设再归档</span></div></template>
